// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * Exhaustive-expectation oracle for the fixed-capacity multinomial resampler: every possible draw outcome of a small
 * finite model is enumerated with its exact probability, so conditional unbiasedness is verified as an identity of the
 * implemented aggregation, not as a statistical approximation.
 */
class FrontierMultinomialResamplerTest {

	@Test
	void exhaustiveOutcomeEnumerationIsConditionallyUnbiased() {
		double[] weights = { 0.5d, 2.0d, 1.5d };
		double total = 4.0d;
		int draws = 4;
		double[][] functionals = {
				{ 1.0d, 1.0d, 1.0d },
				{ 1.0d, 0.0d, 0.0d },
				{ 0.0d, 3.0d, 7.0d },
				{ 2.0d, -1.0d, 0.25d },
		};
		int categories = weights.length;
		int outcomes = 1;
		for (int draw = 0; draw < draws; draw++) {
			outcomes *= categories;
		}
		double probabilityTotal = 0.0d;
		double[] estimateExpectation = new double[functionals.length];
		for (int outcome = 0; outcome < outcomes; outcome++) {
			int code = outcome;
			double probability = 1.0d;
			double[] units = new double[draws];
			int[] expectedCounts = new int[categories];
			for (int draw = 0; draw < draws; draw++) {
				int category = code % categories;
				code /= categories;
				probability *= weights[category] / total;
				units[draw] = midBucketUnit(weights, category);
				expectedCounts[category]++;
			}
			int[] counts = FrontierMultinomialResampler.drawCounts(weights, units);
			assertArrayEquals(expectedCounts, counts,
					"the unit-interval draws must select exactly the enumerated categories");
			int drawTotal = 0;
			double outcomeMass = 0.0d;
			for (int category = 0; category < categories; category++) {
				drawTotal += counts[category];
				outcomeMass += counts[category] * (total / draws);
			}
			assertEquals(draws, drawTotal, "every draw must land in exactly one category");
			assertEquals(total, outcomeMass, 1e-12, "total mass is preserved pathwise, not merely in expectation");
			for (int functional = 0; functional < functionals.length; functional++) {
				double estimate = 0.0d;
				for (int category = 0; category < categories; category++) {
					estimate += counts[category] * (total / draws) * functionals[functional][category];
				}
				estimateExpectation[functional] += probability * estimate;
			}
			probabilityTotal += probability;
		}
		assertEquals(1.0d, probabilityTotal, 1e-12, "the enumerated outcome space must be complete");
		for (int functional = 0; functional < functionals.length; functional++) {
			double truth = 0.0d;
			for (int category = 0; category < weights.length; category++) {
				truth += weights[category] * functionals[functional][category];
			}
			assertEquals(truth, estimateExpectation[functional], 1e-9,
					"the resampled measure must be conditionally unbiased for every linear functional");
		}
	}

	@Test
	void seededDrawsAreDeterministicCompleteAndWeightSensitive() {
		double[] weights = { 1.0d, 3.0d };
		int[] first = FrontierMultinomialResampler.drawCounts(weights, 512, 42L);
		int[] second = FrontierMultinomialResampler.drawCounts(weights, 512, 42L);
		assertArrayEquals(new int[] { 136, 376 }, first,
				"the stateless seed schedule must keep the exact planner sampling sequence stable");
		assertArrayEquals(first, second, "identical seeds must produce identical draw counts");
		assertEquals(512, first[0] + first[1]);
		assertTrue(first[1] > first[0], "the category carrying three quarters of the mass must dominate 512 draws");
	}

	@Test
	void degenerateWeightsAreRejected() {
		assertThrows(IllegalArgumentException.class,
				() -> FrontierMultinomialResampler.drawCounts(new double[] { 1.0d, -1.0d }, 4, 7L));
		assertThrows(IllegalArgumentException.class,
				() -> FrontierMultinomialResampler.drawCounts(new double[] { 0.0d, 0.0d }, 4, 7L));
		assertThrows(IllegalArgumentException.class,
				() -> FrontierMultinomialResampler.drawCounts(new double[] { Double.POSITIVE_INFINITY }, 4, 7L));
	}

	private static double midBucketUnit(double[] weights, int category) {
		double total = 0.0d;
		double before = 0.0d;
		for (int index = 0; index < weights.length; index++) {
			if (index < category) {
				before += weights[index];
			}
			total += weights[index];
		}
		return (before + weights[category] / 2.0d) / total;
	}
}
